  useEffect(()=>{clearTimeout(zenMetadataTimer.current);setZenMetadata(scene==='metadata-error'?'error':'ready');return()=>clearTimeout(zenMetadataTimer.current);},[scene]);
  const retryZenMetadata=()=>{setZenMetadata('loading');zenMetadataTimer.current=setTimeout(()=>setZenMetadata('ready'),420);};
  const zenList = demoZentaoPage(zenTab, zenQuery, zenPage, scene);
